	`did` = CASE WHEN `did` LIKE '%at://%/space/%' THEN (WITH RECURSIVE r(done, todo) AS (SELECT '', `did` UNION ALL SELECT CASE WHEN substr(substr(todo, instr(todo, 'at://') + 5), 1, 4) = 'did:' AND instr(substr(todo, instr(todo, 'at://') + 5), '/') > 0 AND substr(substr(todo, instr(todo, 'at://') + 5), instr(substr(todo, instr(todo, 'at://') + 5), '/'), 7) = '/space/' AND instr(substr(substr(todo, instr(todo, 'at://') + 5), 1, instr(substr(todo, instr(todo, 'at://') + 5), '/') - 1), '"') = 0 THEN done || substr(todo, 1, instr(todo, 'at://') - 1) || 'at:space/' || substr(substr(todo, instr(todo, 'at://') + 5), 1, instr(substr(todo, instr(todo, 'at://') + 5), '/') - 1) || '/' ELSE done || substr(todo, 1, instr(todo, 'at://') + 4) END, CASE WHEN substr(substr(todo, instr(todo, 'at://') + 5), 1, 4) = 'did:' AND instr(substr(todo, instr(todo, 'at://') + 5), '/') > 0 AND substr(substr(todo, instr(todo, 'at://') + 5), instr(substr(todo, instr(todo, 'at://') + 5), '/'), 7) = '/space/' AND instr(substr(substr(todo, instr(todo, 'at://') + 5), 1, instr(substr(todo, instr(todo, 'at://') + 5), '/') - 1), '"') = 0 THEN substr(substr(todo, instr(todo, 'at://') + 5), instr(substr(todo, instr(todo, 'at://') + 5), '/') + 7) ELSE substr(todo, instr(todo, 'at://') + 5) END FROM r WHERE instr(todo, 'at://') > 0) SELECT done || todo FROM r WHERE instr(todo, 'at://') = 0) ELSE `did` END,
	`channel` = CASE WHEN `channel` LIKE '%at://%/space/%' THEN (WITH RECURSIVE r(done, todo) AS (SELECT '', `channel` UNION ALL SELECT CASE WHEN substr(substr(todo, instr(todo, 'at://') + 5), 1, 4) = 'did:' AND instr(substr(todo, instr(todo, 'at://') + 5), '/') > 0 AND substr(substr(todo, instr(todo, 'at://') + 5), instr(substr(todo, instr(todo, 'at://') + 5), '/'), 7) = '/space/' AND instr(substr(substr(todo, instr(todo, 'at://') + 5), 1, instr(substr(todo, instr(todo, 'at://') + 5), '/') - 1), '"') = 0 THEN done || substr(todo, 1, instr(todo, 'at://') - 1) || 'at:space/' || substr(substr(todo, instr(todo, 'at://') + 5), 1, instr(substr(todo, instr(todo, 'at://') + 5), '/') - 1) || '/' ELSE done || substr(todo, 1, instr(todo, 'at://') + 4) END, CASE WHEN substr(substr(todo, instr(todo, 'at://') + 5), 1, 4) = 'did:' AND instr(substr(todo, instr(todo, 'at://') + 5), '/') > 0 AND substr(substr(todo, instr(todo, 'at://') + 5), instr(substr(todo, instr(todo, 'at://') + 5), '/'), 7) = '/space/' AND instr(substr(substr(todo, instr(todo, 'at://') + 5), 1, instr(substr(todo, instr(todo, 'at://') + 5), '/') - 1), '"') = 0 THEN substr(substr(todo, instr(todo, 'at://') + 5), instr(substr(todo, instr(todo, 'at://') + 5), '/') + 7) ELSE substr(todo, instr(todo, 'at://') + 5) END FROM r WHERE instr(todo, 'at://') > 0) SELECT done || todo FROM r WHERE instr(todo, 'at://') = 0) ELSE `channel` END,
	`node_id` = CASE WHEN `node_id` LIKE '%at://%/space/%' THEN (WITH RECURSIVE r(done, todo) AS (SELECT '', `node_id` UNION ALL SELECT CASE WHEN substr(substr(todo, instr(todo, 'at://') + 5), 1, 4) = 'did:' AND instr(substr(todo, instr(todo, 'at://') + 5), '/') > 0 AND substr(substr(todo, instr(todo, 'at://') + 5), instr(substr(todo, instr(todo, 'at://') + 5), '/'), 7) = '/space/' AND instr(substr(substr(todo, instr(todo, 'at://') + 5), 1, instr(substr(todo, instr(todo, 'at://') + 5), '/') - 1), '"') = 0 THEN done || substr(todo, 1, instr(todo, 'at://') - 1) || 'at:space/' || substr(substr(todo, instr(todo, 'at://') + 5), 1, instr(substr(todo, instr(todo, 'at://') + 5), '/') - 1) || '/' ELSE done || substr(todo, 1, instr(todo, 'at://') + 4) END, CASE WHEN substr(substr(todo, instr(todo, 'at://') + 5), 1, 4) = 'did:' AND instr(substr(todo, instr(todo, 'at://') + 5), '/') > 0 AND substr(substr(todo, instr(todo, 'at://') + 5), instr(substr(todo, instr(todo, 'at://') + 5), '/'), 7) = '/space/' AND instr(substr(substr(todo, instr(todo, 'at://') + 5), 1, instr(substr(todo, instr(todo, 'at://') + 5), '/') - 1), '"') = 0 THEN substr(substr(todo, instr(todo, 'at://') + 5), instr(substr(todo, instr(todo, 'at://') + 5), '/') + 7) ELSE substr(todo, instr(todo, 'at://') + 5) END FROM r WHERE instr(todo, 'at://') > 0) SELECT done || todo FROM r WHERE instr(todo, 'at://') = 0) ELSE `node_id` END
WHERE
	`did` LIKE '%at://%/space/%'
	OR `channel` LIKE '%at://%/space/%'
	OR `node_id` LIKE '%at://%/space/%';
